<script setup lang="ts">
import{ref,computed,watch,onUnmounted}from'vue';import{Plus,X,ChartNoAxesColumnIncreasing,Search,RefreshCw}from'lucide-vue-next';import type{City,Office,Result}from'../../types/election';import{elections}from'../../repositories/elections';import{percent,number,normalize,palette,time}from'../../utils/format';
const props=defineProps<{uf:string;cities:City[];office:Office}>();const selected=ref<string[]>([]),results=ref<Record<string,Result>>({}),errors=ref<Record<string,string>>({}),loading=ref(false),picker=ref(false),query=ref(''),view=ref('chart');let generation=0;const choices=computed(()=>props.cities.filter(c=>!selected.value.includes(c.slug)&&normalize(c.name).includes(normalize(query.value))).slice(0,30));const candidates=computed(()=>{const values=Object.values(results.value);const dict=new Map(values.flatMap(r=>r.candidates.map(c=>[c.id,c]as const)));return [...dict.values()].sort((a,b)=>values.reduce((s,r)=>s+(r.candidates.find(c=>c.id===b.id)?.votes||0),0)-values.reduce((s,r)=>s+(r.candidates.find(c=>c.id===a.id)?.votes||0),0))});async function refresh(){const g=++generation;loading.value=true;await Promise.all(selected.value.map(async s=>{try{const data=await elections.result(props.uf,s,props.office);if(g===generation){results.value[s]=data;delete errors.value[s]}}catch{if(g===generation)errors.value[s]='Consulta indisponível'}}));if(g===generation)loading.value=false}function add(s:string){if(selected.value.length>=4)return;selected.value.push(s);picker.value=false;query.value='';void refresh()}function remove(s:string){generation++;selected.value=selected.value.filter(x=>x!==s);delete results.value[s];delete errors.value[s];loading.value=false}watch(()=>[props.uf,props.office],()=>{generation++;results.value={};errors.value={};if(selected.value.length&&props.cities.some(c=>c.slug===selected.value[0]))void refresh();else selected.value=[]});
const interval=setInterval(()=>{if(selected.value.length&&!document.hidden&&!loading.value)void refresh()},30000);onUnmounted(()=>{generation++;clearInterval(interval)});
</script>
<template><section id="comparar" class="panel comparison-panel"><div class="panel-heading"><div><h2><ChartNoAxesColumnIncreasing :size="20"/> Comparar municípios</h2><p>Até 4 cidades do mesmo estado, lado a lado</p></div><button v-if="selected.length" class="icon-button" aria-label="Atualizar comparação" @click="refresh"><RefreshCw :size="17" :class="{spinning:loading}"/></button></div><div class="comparison-picks"><span v-for="s in selected" :key="s" class="city-chip">{{cities.find(c=>c.slug===s)?.name}}<button :aria-label="'Remover '+s" @click="remove(s)"><X :size="14"/></button></span><button v-if="selected.length<4" class="add-city" @click="picker=!picker"><Plus :size="16"/>Adicionar município</button></div><div v-if="picker" class="comparison-picker"><label class="input-search"><Search :size="17"/><input v-model="query" placeholder="Buscar município" aria-label="Buscar município para comparar"></label><div><button v-for="c in choices" :key="c.code" @click="add(c.slug)">{{c.name}}<Plus :size="15"/></button><p v-if="!choices.length">Nenhum município disponível.</p></div></div><div v-if="!selected.length" class="comparison-empty"><ChartNoAxesColumnIncreasing :size="30"/><p>Como votaram as cidades do seu estado?</p><span>Adicione municípios para comparar os resultados do cargo selecionado.</span></div><template v-else><div class="comparison-toolbar"><div class="segmented"><button :class="{active:view==='chart'}" @click="view='chart'">Gráfico</button><button :class="{active:view==='table'}" @click="view='table'">Tabela</button></div><span class="small muted">{{loading?'Consultando o TSE…':'Percentuais oficiais por município'}}</span></div><div v-if="view==='chart'" class="comparison-charts"><div v-for="s in selected" :key="s" class="city-chart"><h3>{{cities.find(c=>c.slug===s)?.name}}</h3><p v-if="errors[s]" class="small warning-text">{{errors[s]}}{{results[s]?' · Última leitura mantida':''}}</p><div v-for="(c,i) in candidates.slice(0,4)" :key="c.id" class="comparison-bar"><div><span>{{c.name}}</span><strong>{{percent(results[s]?.candidates.find(x=>x.id===c.id)?.percent)}}</strong></div><div class="candidate-bar"><span :style="{width:(results[s]?.candidates.find(x=>x.id===c.id)?.percent||0)+'%',background:palette[i]}"></span></div></div><span class="small muted">{{time(results[s]?.updatedAt)}} · Brasília</span></div></div><div v-else class="table-scroll"><table><thead><tr><th>Município</th><th v-for="c in candidates" :key="c.id">{{c.name}}</th></tr></thead><tbody><tr v-for="s in selected" :key="s"><th>{{cities.find(c=>c.slug===s)?.name}}</th><td v-for="c in candidates" :key="c.id"><strong>{{percent(results[s]?.candidates.find(x=>x.id===c.id)?.percent)}}</strong><small>{{number(results[s]?.candidates.find(x=>x.id===c.id)?.votes)}} votos</small></td></tr></tbody></table></div><div class="panel-footnote">{{view==='chart'?'O gráfico destaca até 4 candidatos; a tabela apresenta todos. ':''}}Cada município pode ter um horário de atualização diferente.</div></template></section></template>
